insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('BT', 'default', 'Bhutan reference chart of accounts', '{}'::jsonb, true, 'companies', array['BT-IFRS-IS', 'BT-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Bhutan. The Companies Act of Bhutan 2016 requires every body corporate to prepare financial statements in compliance with the Bhutanese Accounting Standards the Accounting and Auditing Standards Board prescribes, and the IFRS for SMEs Standard is adopted in its entirety as the Bhutan Accounting Standard for SMEs, required for unlisted companies. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements below, with the accounts a Bhutanese company actually keeps — GST input and output tax, the GST settlement account owed to or by the Department of Revenue and Customs, import GST owed at customs clearance, personal income tax and tax withheld at source payable, pension and provident fund contributions.', 'ifrs-profile')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

