   applies_supply_vs_seller)
values
  ('BT', 'BT-P-5', 'Purchase, standard rate 5 %', '{}'::jsonb, 'A taxable purchase at the standard rate whose input tax is deducted', 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 32 and following — a taxable person is allowed a credit for the input tax incurred on an acquisition made for the purpose of its taxable supplies; s. 44 — the net amount of the return is the output tax less the allowable input tax credits; Schedule I, paragraph 1 — 5 %. Deducted in full when the purchase serves taxable or zero-rated supplies only; s. 36 and s. 37 apportion the credit when it also serves exempt supplies, which this code does not do.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-P-5-ND', 'Purchase, standard rate 5 %, input tax not deductible', '{}'::jsonb, 'A purchase whose input tax the Act blocks — entertainment, club memberships, passenger vehicles and what is used with them', 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 34 — no input tax credit for an acquisition used to provide entertainment (unless entertainment is the person''s economic activity), for a membership of a sporting, social or recreational club, for a lottery supply, for the acquisition or import of a passenger vehicle, or for goods or services used directly in connection with one. The tax charged by the supplier follows the expense to account 6530 and reaches no box.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-P-EX', 'Purchase, exempt', '{}'::jsonb, 'An exempt supply bought for the business', 'percent', 0, 'purchase', 'exempt', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 26 and Schedule IV — an exempt supply bought for the business (financial services, residential lease, education, health and the listed goods): no GST is charged and no input tax arises; the return has no row for an exempt purchase.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-P-IMP', 'Import of goods, GST paid at customs clearance', '{}'::jsonb, 'GST charged on a taxable import, paid at customs clearance and claimed as input tax', 'percent', 5, 'purchase', 'import', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 12 and s. 14(2) — GST applies to a taxable import and the importer is liable; s. 47 — the GST on a taxable import is paid at customs clearance under the Customs Act of Bhutan 2017; s. 32 — the importer deducts it as input tax in its return. Posted to 2125 (import GST payable at the border) until the customs payment is matched.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-P-RC-SVC', 'Imported B2B service, reverse-charged and deductible', '{}'::jsonb, 'A service supplied by a person outside Bhutan to a business customer in Bhutan, taxed to the recipient who may deduct the tax', 'percent', 5, 'purchase', 'foreign_services_received', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 14(3) — the purchaser is liable for GST on a taxable supply of imported business-to-business services; s. 33 — the customer is treated as incurring both output tax and input tax and is allowed the input tax credit provided it has accounted for the output tax; s. 18 — the value of the imported B2B service. The output tax is declared in box 1R and the credit in box 2R, so the net effect for a fully taxable customer is nil.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-S-5', 'Sale, standard rate 5 %', '{}'::jsonb, 'The general rate on a taxable supply of goods or services made in Bhutan', 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Goods and Services Tax Act of Bhutan 2020 (consolidated with the amendments of 2021, 2022 and 2025), s. 12 — GST applies to taxable supplies and taxable imports; s. 14(1) — the supplier is liable on a taxable supply made within Bhutan; s. 16 and s. 25 — the tax is the rate of Schedule I applied to the value of the supply; Schedule I, paragraph 1 — "Other than the zero rate prescribed in Schedule V, the applicable GST rate on taxable supplies and taxable imports of goods and services shall be 5%" (amended by the GST (Amendment) Act of Bhutan 2025); s. 2 — the Act is in force from 1 January 2026 and does not apply retroactively. Every supply that is neither exempt (Schedule IV) nor zero-rated (Schedule V) is standard-rated.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply Schedule IV exempts: residential lease, financial services, education, health, rice, edible oil, salt', 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 26 — GST does not apply to an exempt supply listed in Schedule IV; s. 27 — the supplier has no input tax credit to the extent an acquisition is for making an exempt supply. Schedule IV, A: paragraph 2 (right to occupy and reside in residential premises), paragraph 3 (sale of residential premises, except the first sale of a newly built one), paragraph 5 (financial services, except a specific fee), paragraph 10 (education services), paragraph 11 (health services); Schedule IV, C: rice, edible oils of the listed headings, salt, carriages for disabled persons, sanitary towels and nappies, by Bhutan Trade Classification code.', 'E', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null),
  ('BT', 'BT-S-Z-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'Goods declared for export and exported, services supplied to a customer outside Bhutan, international transport (Schedule V)', 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'GST Act of Bhutan 2020, s. 28 — GST applies at zero per cent to a zero-rated supply; Schedule V, paragraph 2 — a sale of goods declared for export under the Customs Act of Bhutan 2017 and exported (or sold by a licensed duty-free vendor to a tourist on proof of exit); paragraph 9 — services supplied to a customer outside Bhutan who uses or enjoys them outside Bhutan; paragraph 12 — international transport and related services. A zero-rated supply is a taxable supply: s. 29 keeps the input tax credit for the purpose of making it.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'gst-act', null, null, null, null)
