insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BT', 'BT-GST-RETURN', 'Monthly Goods and Services Tax return', array['month']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Goods and Services Tax Act of Bhutan 2020, s. 105 of the definitions — the tax period is a calendar month, or another period the rules prescribe; s. 38 — a taxable person files a GST return no later than thirty days after the end of each tax period; s. 42 — the person self-assesses the GST and files; s. 44 — the net amount is the output tax, less the input tax credits, plus or minus adjustments; s. 46 — a positive net amount is paid when the return is filed. The return form is filed on RAMIS and was not readable from the machine this pack was written on: the rows below are this pack''s own, grouped under those figures, and the gap is recorded in this pack''s README.', true,'day_of_month_after_period'::filing_deadline_rule, 30, null, 'GST Act of Bhutan 2020, s. 38 — no later than thirty days after the end of the tax period. Thirty days after a month''s end falls on the 30th of the next month for every month but January (2 March, or 1 March in a leap year); the pack carries day 30 and the difference is recorded in its README. The late-filing penalty is not modelled.', 'gst-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

