update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'GST Act of Bhutan 2020, s. 209 and the definition of ''tax invoice'' — a tax invoice carries the particulars the rules and regulations prescribe; the Act does not forbid a gap in the numbering, which is why `numbering` is `sequential` and not `gapless_per_year`. The particulars could not be read from the consolidated Act alone and are recorded in this pack''s README as a gap.',
  numbering_source_key          = 'gst-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'GST Act of Bhutan 2020, s. 81 — GST on a taxable supply becomes payable at the earlier of the time an invoice for the supply is issued and the time any part of the consideration is paid. Ekwo''s closed vocabulary has no value for ''invoice or payment, whichever comes first''; `invoice_date` is the nearest, and the gap — a payment received before the invoice, which s. 81(2) makes the tax point — is recorded in this pack''s README.',
  tax_point_source_key          = 'gst-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Bhutanese statute obliges a business to exchange a structured electronic invoice with another business in the sense Ekwo''s vocabulary gives the word: there is no Peppol authority, no published profile and no scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. Returns are filed online on RAMIS, which is a tax-administration portal and not an invoice exchange. If the Department publishes an e-invoicing rule, this field is where it goes.',
  einvoice_source_key           = 'ramis',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'BT';

update country_defaults set
  tax_payee_name       = 'Department of Revenue and Customs, Ministry of Finance',
  tax_payee_source_key = 'ramis'
 where country = 'BT';
